// Adapter pattern adapted from leari-mail/leari, commit 5876482 (MIT, Pablo Souza).
// The schema is generated by Drizzle; Rust applies migrations and owns transactional writes.
import { invoke } from "@tauri-apps/api/core";
import Database from "@tauri-apps/plugin-sql";
import { drizzle } from "drizzle-orm/sqlite-proxy";
import * as schema from "@/db/schema";

let connection: Promise<Database> | undefined;
function getConnection() {
  connection ??= invoke<string>("database_path").then((path) => Database.load(`sqlite:${path}`))
    .catch((error: unknown) => { connection = undefined; throw error; });
  return connection;
}
export const db = drizzle<typeof schema>(async (sql, params, method) => {
  // Reads only: ownership mutations must pass through native game/file guards.
  if (method === "run" || !/^\s*select\b/i.test(sql) || sql.includes(";")) throw new Error("Use a native command for launcher database writes.");
  const result = await (await getConnection()).select<Record<string, unknown>[]>(sql, params);
  const rows = result.map((row) => Object.values(row));
  return { rows: method === "get" ? (rows[0] ?? []) : rows };
}, { schema });
